// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type GlowingIconProps = Record<string, any>;

const GlowingIcon: React.FC<GlowingIconProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  circleColor = "#ffffff",
  textColor = "#000000",
  textContent = "???",
  circleSize = 400,
  glowRadius = 40,
  pulseSpeed = 2,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Background Logic
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Pulse Logic
  // We use a sine wave based on the frame count and pulse speed
  const wave = Math.sin((frame / fps) * pulseSpeed * Math.PI);
  
  // Interpolate the wave (-1 to 1) to usable animation values
  const scale = interpolate(wave, [-1, 1], [1, 1.05], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const glowOpacity = interpolate(wave, [-1, 1], [0.4, 0.7], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const glowScale = interpolate(wave, [-1, 1], [1.1, 1.25], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          position: "relative",
          width: circleSize,
          height: circleSize,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {/* Ambient Glow Layer - Blurred duplicate of the circle */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            borderRadius: "50%",
            backgroundColor: circleColor,
            filter: `blur(${glowRadius}px) saturate(1.5)`,
            opacity: glowOpacity,
            transform: `scale(${glowScale})`,
            transition: "none", // STRICT ANIMATION RULE
          }}
        />

        {/* Main Circle & Text Layer */}
        <div
          style={{
            position: "relative",
            width: "100%",
            height: "100%",
            borderRadius: "50%",
            backgroundColor: circleColor,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transform: `scale(${scale})`,
            zIndex: 1,
            transition: "none", // STRICT ANIMATION RULE
            filter: "drop-shadow(0px 0px 10px rgba(0,0,0,0.3))", // Slight shadow for separation
          }}
        >
          <span
            style={{
              fontFamily: interFamily,
              fontSize: circleSize * 0.45,
              fontWeight: 700,
              color: textColor,
              lineHeight: 1,
              transition: "none",
            }}
          >
            {textContent}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default GlowingIcon;